-- ============================================================
-- P2: courses 改为"服务端权威",客户端不能再写
--
-- 之前:任何登录用户都能 insert / update courses 里的任何一行(RLS 策略是
-- auth.role() = 'authenticated'),save_round 还会把客户端传来的球场写进去。
-- 球场数据是所有人共用的 —— 一个人可以把别人要打的球场评分改成任意值,
-- 或抢先用一个编造的数据占住某个 id,污染所有人的 handicap 计算。
--
-- 现在:
--   * 262 个核实过的球场(含每洞标准杆 holes_par)作为种子写进库里,来源就是客户端的
--     src/data/courses.ts,由脚本生成,测试保证两边一致
--   * courses 对客户端只读;已有的 7 个球场也会按这份数据校正
--   * save_round 不再写 courses:球场不存在 → unknown_course;
--     提交的每洞标准杆必须和库里一致 → 否则 invalid_holes
--     (这样也就不能靠改标准杆来操纵相对标准杆和 Crew 里别人看到的 HCP)
--   * 函数签名不变,旧版客户端仍然能用(多传的球场字段会被忽略)
-- ============================================================
alter table public.courses add column if not exists holes_par int[];

-- BEGIN COURSES SEED (generated by scripts/gen-courses-seed.cjs — do not edit by hand)
on conflict (id) do update set
  name = excluded.name, city = excluded.city, state = excluded.state,
  course_rating = excluded.course_rating, slope_rating = excluded.slope_rating,
  total_par = excluded.total_par, holes_par = excluded.holes_par;
-- END COURSES SEED

-- 球场表对客户端只读
drop policy if exists "Authenticated users can upsert courses" on public.courses;
drop policy if exists "Authenticated users can update courses" on public.courses;
revoke all on public.courses from anon, authenticated;
grant select on public.courses to anon, authenticated;     -- "Anyone can read courses" 策略保持不变

create or replace function public.save_round(
  p_course   jsonb,   -- 只用其中的 id;其余字段忽略(球场数据以库里为准)
  p_tee_box  text,
  p_date     date,    -- 客户端的本地日期(避免 UTC 在美西傍晚算成"明天")
  p_holes    jsonb    -- [{hole_number, par, strokes, putts, troubles: [...]}, ...]
) returns uuid
language plpgsql security invoker set search_path = public as $$
declare
  v_uid      uuid := auth.uid();
  v_n        int;
  v_round    uuid;
  v_strokes  int;
  v_putts    int;
  v_par      int;
  v_valid    boolean;
  v_distinct int;
  v_course   text := nullif(btrim(p_course ->> 'id'), '');
  v_holes_par int[];
  v_known    boolean;
begin
  if v_uid is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;
  if v_course is null or length(v_course) > 100 then
    raise exception 'invalid_course' using errcode = '22023';
  end if;
  if p_holes is null or jsonb_typeof(p_holes) <> 'array' then
    raise exception 'invalid_holes' using errcode = '22023';
  end if;

  v_n := jsonb_array_length(p_holes);
  if v_n not in (9, 18) then
    raise exception 'invalid_holes' using errcode = '22023';
  end if;

  -- 球场必须已经在库里(种子);不再接受客户端自带的球场数据
  select true, holes_par into v_known, v_holes_par from public.courses where id = v_course;
  if v_known is not true then
    raise exception 'unknown_course' using errcode = '22023';
  end if;

  -- 一次聚合同时完成逐洞校验和汇总;任何一洞不合法 v_valid 即为 false
  select
    -- bool_and 会忽略 NULL,所以每洞先 coalesce 成 false:缺字段的洞一律判为不合法
    coalesce(bool_and(coalesce(
      hole_number between 1 and 18
      and par     between 3 and 6
      and strokes between 1 and 20
      and putts   between 0 and 10 and putts <= strokes
      and coalesce(troubles, '{}') <@ array['water','ob','bunker','rough','other']
      -- 有每洞标准杆数据的球场:提交的标准杆必须一致
      and (v_holes_par is null or par = v_holes_par[hole_number]),
      false)), false),
    count(distinct hole_number),
    sum(strokes), sum(putts), sum(par)
  into v_valid, v_distinct, v_strokes, v_putts, v_par
  from jsonb_to_recordset(p_holes)
    as x(hole_number int, par int, strokes int, putts int, troubles text[]);

  if not v_valid or v_distinct <> v_n then
    raise exception 'invalid_holes' using errcode = '22023';
  end if;

     v_n, v_strokes, v_putts, v_strokes - v_par)
  returning id into v_round;

  select v_round, hole_number, par, strokes, putts, coalesce(troubles, '{}')
  from jsonb_to_recordset(p_holes)
    as x(hole_number int, par int, strokes int, putts int, troubles text[]);

  return v_round;
end $$;

revoke execute on function public.save_round(jsonb, text, date, jsonb) from public, anon;
grant  execute on function public.save_round(jsonb, text, date, jsonb) to authenticated;
